// === Tab: mySketch ===
// let Risou
// https://risoume.github.io/

let n, prev, curr;
let s;
let mult = 0.8;
let colors = ["#F0D8A8", "#3D1C00", "#86B8B1", "#F2D694", "#FA2A00"];

function setup() {
  createCanvas(600, 600);
  rectMode(RADIUS);
  noLoop();
  init();
}

function init() {
  n = int(random(4, 8));
  s = width/(n+1);
}

function draw() {
  background("#fffbe6");
  stroke(0);
  for (i = 0; i < n; i++) {
    for (j = 0; j < n; j++) {
      if (random(1) < 0.5) {
        circles((i+1)*s, (j+1)*s, s*mult);
      } else {
        rects((i+1)*s, (j+1)*s, s*mult/2);
      }
    }
  }
}

function circles(x, y, size) {
  pushMatrix();
  translate(x, y);
  prev = int(random(colors.length));
  fill(colors[prev]);
  strokeWeight(2);
  ellipse(0, 0, size, size);

  let angle = random(-PI, PI); 
  rotate(angle);
  curr = int(random(colors.length));
  while (curr == prev) {
    curr = int(random(colors.length));
  }
  fill(colors[curr]);
  strokeWeight(1);
  ellipse(size/4, 0, size/2, size/2);
  popMatrix();
}

function rects(x, y, size) {
  pushMatrix();
  translate(x, y);
  prev = int(random(colors.length));
  fill(colors[prev]);
  strokeWeight(2);
  rect(0, 0, size, size);
  float[][] coor = {{0, 0}, {size/2, 0}, {0, size/2}, {-size/2, 0}, {0, -size/2}};

  let q = int(random(coor.length));
  translate(coor[q][0], coor[q][1]);
  curr = int(random(colors.length));
  while (curr == prev) {
    curr = int(random(colors.length));
  }
  fill(colors[curr]);
  strokeWeight(1);
  rect(0, 0, size/2, size/2);
  popMatrix();
}

function mouseReleased() {
  init();
  redraw();
}

